def calc(expr: str) -> int | str:
    n = len(expr)
    pos = 0

    def skip_ws() -> None:
        nonlocal pos
        while pos < n and expr[pos].isspace():
            pos += 1

    def parse_primary() -> int:
        nonlocal pos
        skip_ws()
        if expr[pos] == '(':
            pos += 1
            val = parse_add()
            skip_ws()
            pos += 1
            return val
        start = pos
        while pos < n and '0' <= expr[pos] <= '9':
            pos += 1
        return int(expr[start:pos])

    def parse_unary() -> int:
        nonlocal pos
        items: list[tuple[int, int]] = []
        while True:
            neg = 0
            while True:
                skip_ws()
                if pos < n and expr[pos] == '-':
                    neg ^= 1
                    pos += 1
                else:
                    break
            base = parse_primary()
            items.append((neg, base))
            skip_ws()
            if pos < n and expr[pos] == '^':
                pos += 1
            else:
                break

        acc = items[-1][1]
        if items[-1][0]:
            acc = -acc
        for i in range(len(items) - 2, -1, -1):
            neg_i, base_i = items[i]
            if acc < 0:
                raise ValueError
            acc = base_i ** acc
            if neg_i:
                acc = -acc
        return acc

    def parse_mul() -> int:
        nonlocal pos
        val = parse_unary()
        while True:
            skip_ws()
            if pos >= n:
                break
            op = expr[pos]
            if op not in ('*', '/', '%'):
                break
            pos += 1
            rhs = parse_unary()
            if op == '*':
                val *= rhs
            elif op == '/':
                if rhs == 0:
                    raise ValueError
                q = abs(val) // abs(rhs)
                val = -q if (val < 0) ^ (rhs < 0) else q
            else:
                if rhs == 0:
                    raise ValueError
                q = abs(val) // abs(rhs)
                if (val < 0) ^ (rhs < 0):
                    q = -q
                val = val - rhs * q
        return val

    def parse_add() -> int:
        nonlocal pos
        val = parse_mul()
        while True:
            skip_ws()
            if pos >= n:
                break
            op = expr[pos]
            if op not in ('+', '-'):
                break
            pos += 1
            rhs = parse_mul()
            if op == '+':
                val += rhs
            else:
                val -= rhs
        return val

    try:
        return parse_add()
    except ValueError:
        return "error"
